"use client";

import { loadVariableFont } from "@remotion/google-fonts/Urbanist";
import type React from "react";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  interpolate,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  DEFAULT_AFTER,
  DEFAULT_BEFORE,
  phrasesOf,
  type TwoHitElementId,
  twoHitTimeline,
} from "./timeline";

const urbanist = loadVariableFont("normal", { subsets: ["latin"] });

export interface TwoHitProps {
  before?: string;
  after?: string;
  hitAt?: number;
  /** Frames between the first, small hit and the second, full one. */
  hitGap?: number;
  fontWeight?: number;
  accent?: string;
  /** Text color; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the lines. Load it yourself; Urbanist by default. */
  fontFamily?: string;
  /** Size of the lines, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
  /**
   * Moves, trims or stretches the lines rising and the two hits, by the ids
   * in `./timeline`. Frames on the scene timeline, after `delay` and `speed`.
   */
  timing?: Timing<TwoHitElementId>;
}

const THEMES = {
  dark: { bg: "#0B0B0B", ink: "#FFFFFF", blue: "#2F6BFF" },
  light: { bg: "#FFFFFF", ink: "#0A0A0A", blue: "#1F4FE0" },
} as const;

const WGHT = 400;
const REST = -0.035;
const FIRST_GAIN = 0.32;
const MAX_TRACK = 0.75;

const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const EASE_ATTACK = Easing.bezier(0.2, 0.9, 0.3, 1);
const EASE_RELEASE = Easing.bezier(0.45, 0, 0.15, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface Metrics {
  widths: number[][];
  baseline: number;
  cap: number;
}

function measure(phrases: string[][], font: string): Metrics {
  const canvas = document.createElement("canvas");
  const ctx = canvas.getContext("2d");
  let widths = phrases.map((lines) => lines.map((l) => l.length * 0.5));
  let baseline = 0.8;
  let cap = 0.7;
  if (ctx) {
    ctx.font = font;
    widths = phrases.map((lines) =>
      lines.map((l) => ctx.measureText(l).width / 200),
    );
    const fm = ctx.measureText("H");
    const asc = fm.fontBoundingBoxAscent / 200;
    const desc = fm.fontBoundingBoxDescent / 200;
    baseline = (1 - (asc + desc)) / 2 + asc;
    cap = fm.actualBoundingBoxAscent / 200;
  }
  return { widths, baseline, cap };
}

function useMetrics(phrases: string[][], fontFamily: string, weight: number) {
  const key = phrases.map((l) => l.join("\u0002")).join("\u0001");
  const [state, setState] = useState<{ key: string; m: Metrics } | null>(null);
  const [handle] = useState(() => delayRender("two-hit: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const list = key.split("\u0001").map((l) => l.split("\u0002"));
    Promise.all([
      urbanist.waitUntilDone(),
      document.fonts.load(`${weight} 100px "${fontFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        if (!live) return;
        setState({
          key,
          m: measure(list, `${weight} 200px "${fontFamily}"`),
        });
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
    };
  }, [key, fontFamily, weight, handle]);
  return state && state.key === key ? state.m : null;
}

function pulse(x: number, attack: number, hold: number, release: number) {
  if (x <= 0) return 0;
  if (x < attack) return EASE_ATTACK(x / attack);
  if (x < attack + hold) return 1;
  return 1 - EASE_RELEASE(Math.min(1, (x - attack - hold) / release));
}

function normalizeHex(c: string | undefined, fallback: string) {
  if (c && /^#([0-9a-fA-F]{3}|[0-9a-fA-F]{6})$/.test(c)) return c;
  return fallback;
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function TwoHit(props: TwoHitProps) {
  const {
    before = DEFAULT_BEFORE,
    after = DEFAULT_AFTER,
    fontWeight = WGHT,
    accent,
    ink,
    background,
    fontFamily = urbanist.fontFamily,
    scale = 1,
    delay = 0,
    speed = 1,
    theme = "dark",
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    twoHitTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const c = THEMES[theme];
  const fg = ink ?? c.ink;
  const blue = normalizeHex(accent, c.blue);
  const phrases = useMemo(() => phrasesOf(before, after), [before, after]);
  const m = useMetrics(phrases, fontFamily, fontWeight);

  const transparent = background === "transparent";
  const stage = transparent ? "transparent" : (background ?? c.bg);

  if (!m) {
    return (
      <div style={{ position: "absolute", inset: 0, background: stage }} />
    );
  }

  const portrait = H > W * 1.1;
  const margin = W * (portrait ? 0.06 : 0.055);
  const span = W - margin * 2;
  const lens = phrases.map((lines) => lines.map((l) => Array.from(l).length));
  const restW = (i: number, j: number) =>
    m.widths[i][j] + REST * (lens[i][j] - 1);
  let widest = 0;
  phrases.forEach((lines, i) => {
    lines.forEach((_, j) => {
      widest = Math.max(widest, restW(i, j));
    });
  });
  const rows = Math.max(phrases[0].length, phrases[1].length);
  const LEAD = 0.98;
  const F = Math.min(
    (W * (portrait ? 0.86 : 0.62)) / widest,
    (H * (portrait ? 0.3 : 0.62)) / (m.cap + (rows - 1) * LEAD),
  );
  const peak = (i: number, j: number) =>
    Math.min(
      MAX_TRACK,
      Math.max(REST, (span / F - m.widths[i][j]) / Math.max(1, lens[i][j] - 1)),
    );

  const hit1 = tl.get("hit:0");
  const hit2 = tl.get("hit:1");
  const swapAt = hit2.start + hit2.beat("swap");
  const pulseOf = (hit: typeof hit1) =>
    pulse(
      t - hit.start,
      hit.beat("attack"),
      hit.beat("hold"),
      hit.beat("release"),
    );
  const e1 = FIRST_GAIN * pulseOf(hit1);
  const e2 = pulseOf(hit2);
  const e = Math.max(e1, e2);
  const idx = t < swapAt ? 0 : 1;
  const lines = phrases[idx];

  const enterAt = (j: number, f: number) => {
    const line = tl.get(`line:${j}`);
    return interpolate(f, [line.start, line.end], [0, 1], {
      ...CLAMP,
      easing: EASE_OUT,
    });
  };
  const enter = (j: number) => enterAt(j, t);
  // The rise is a long ease-out, so its tail still crosses pixels well after
  // the progress looks settled: test the travel itself against its neighbours.
  const rising = (j: number) => {
    const rise = (f: number) => (1 - enterAt(j, f)) * F * 1.05;
    return (
      Math.abs(rise(t + 1) - rise(t)) > 1e-3 ||
      Math.abs(rise(t) - rise(t - 1)) > 1e-3
    );
  };

  const blockH = (m.cap + (lines.length - 1) * LEAD) * F;
  const firstBase = H * (portrait ? 0.5 : 0.53) - blockH / 2 + m.cap * F;

  return (
    <AbsoluteFill
      style={{
        background: stage,
        overflow: "hidden",
        fontFamily,
      }}
    >
      <ScaleLayer scale={scale}>
        {lines.map((line, j) => {
          const track = REST + e * (peak(idx, j) - REST);
          const baseY = firstBase + j * LEAD * F;
          const p = enter(j);
          const last = j === lines.length - 1 && lines.length > 1;
          return (
            <div
              key={`${idx}-${j}`}
              style={{
                position: "absolute",
                right: margin,
                top: baseY - m.baseline * F - F * 0.1,
                height: F * 1.25,
                overflow: "hidden",
              }}
            >
              <div
                style={{
                  paddingTop: F * 0.1,
                  fontSize: F,
                  lineHeight: `${F}px`,
                  fontWeight,
                  fontVariationSettings: `"wght" ${fontWeight}`,
                  letterSpacing: `${track.toFixed(4)}em`,
                  marginRight: `${(-track).toFixed(4)}em`,
                  whiteSpace: "pre",
                  color: last ? blue : fg,
                  transform: `translateY(${((1 - p) * F * 1.05).toFixed(2)}px)${glide(rising(j))}`,
                }}
              >
                {line}
              </div>
            </div>
          );
        })}
      </ScaleLayer>
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The lines rise in, a small hit spreads the letters, then a full hit swaps
// the copy. Frames on the 30 fps scene timeline, after `delay` and `speed`.
// The ids are public: a saved `timing` prop refers to them.

export type TwoHitElementId = `line:${number}` | "hit:0" | "hit:1";

export interface TwoHitTimingProps {
  before?: string;
  after?: string;
  hitAt?: number;
  hitGap?: number;
}

export const DEFAULT_BEFORE = "Premieres Friday.";
export const DEFAULT_AFTER = "Streaming now.";
const HIT_AT = 34;
const HIT_GAP = 24;
/** Line `j` rises over `RISE` frames from `ENTER_AT + j * ENTER_STAGGER`. */
const ENTER_AT = 2;
const ENTER_STAGGER = 4;
const RISE = 18;

/** A phrase as its lines: the last word on a line of its own. */
export function splitLast(text: string) {
  const clean = text.trim().replace(/\s+/g, " ");
  const i = clean.lastIndexOf(" ");
  if (i < 0) return [clean];
  return [clean.slice(0, i), clean.slice(i + 1)];
}

/** Both phrases, with the fallbacks an empty one gets. */
export function phrasesOf(before: string, after: string) {
  return [
    splitLast(before.trim() || "Soon."),
    splitLast(after.trim() || "Now."),
  ];
}

// `line:<j>` is row j rising in. Each hit swells the tracking over `attack`,
// holds and lets go over `release`; the second hit swaps to `after` at its
// `swap` beat.
export const twoHitTimeline = defineTimeline<
  TwoHitElementId,
  TwoHitTimingProps
>(
  ({
    before = DEFAULT_BEFORE,
    after = DEFAULT_AFTER,
    hitAt = HIT_AT,
    hitGap = HIT_GAP,
  }) => {
    const phrases = phrasesOf(before, after);
    const rows = Math.max(phrases[0].length, phrases[1].length);
    const lines = Array.from(
      { length: rows },
      (_, j): TimelineElement<TwoHitElementId> => ({
        id: `line:${j}`,
        lane: "Lines",
        label: phrases[0][j] ?? phrases[1][j],
        start: ENTER_AT + j * ENTER_STAGGER,
        length: RISE,
        follows: j > 0 ? `line:${j - 1}` : undefined,
      }),
    );
    const h1 = hitAt;
    const h2 = hitAt + hitGap;
    const hits: TimelineElement<TwoHitElementId>[] = [
      {
        id: "hit:0",
        lane: "Hits",
        label: "small hit",
        start: h1,
        length: 4 + 0 + 16,
        beats: { attack: 4, hold: 0, release: 16 },
      },
      {
        id: "hit:1",
        lane: "Hits",
        label: "full hit",
        start: h2,
        length: 5 + 4 + 24,
        follows: "hit:0",
        beats: { attack: 5, hold: 4, release: 24, swap: 7 },
      },
    ];
    return [...lines, ...hits].sort((a, b) => a.start - b.start);
  },
);
